  sliders?: readonly LayoutSlider[];
  /**
   * Buttons and dropdowns over the chart that call `restyle`, `relayout`, `update` or `animate` (plan E5.10).
   */
  updatemenus?: readonly LayoutUpdatemenu[];
  /**
   * A 3D scene. `scene2`, `scene3`, … declare more, referenced from 3D traces' `scene` (`'scene2'`).
   */
  scene?: LayoutScene;
  /**
   * Subplot `scene2`: the same attributes as `scene`.
   */
  scene2?: LayoutScene;
  /**
   * Subplot `scene3`: the same attributes as `scene`.
   */
  scene3?: LayoutScene;
  /**
   * Subplot `scene4`: the same attributes as `scene`.
   */
  scene4?: LayoutScene;
  /**
   * Subplot `scene5`: the same attributes as `scene`.
   */
  scene5?: LayoutScene;
  /**
   * Subplot `scene6`: the same attributes as `scene`.
   */
  scene6?: LayoutScene;
  /**
   * Subplot `scene7`: the same attributes as `scene`.
   */
  scene7?: LayoutScene;
  /**
   * Subplot `scene8`: the same attributes as `scene`.
   */
  scene8?: LayoutScene;
  /**
   * Subplot `scene9`: the same attributes as `scene`.
   */
  scene9?: LayoutScene;
  /**
   * Further `scene` containers (`scene10`, …): the same attributes as `scene`, not type-checked.
   */
  [key: `scene${number}`]: unknown;
  /**
   * The 2.5D view (Holochart extension): every cartesian subplot in perspective, its plot area a tilted plane; axes, hover, zoom and selection keep working.
   */
  view3d?: LayoutView3d;
