  /**
   * Box height (text area), px. Default: the text height.
   *
   * Minimum: 1
   */
  height?: number;
  /**
   * Opacity of the whole annotation.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  opacity?: number;
  /**
   * Horizontal alignment of the lines inside the box.
   *
   * @defaultValue `"center"`
   */
  align?: 'left' | 'center' | 'right';
  /**
   * Vertical alignment of the text inside the box (with `height`).
   *
   * @defaultValue `"middle"`
   */
  valign?: 'top' | 'middle' | 'bottom';
  /**
   * Box background.
   *
   * @defaultValue `"rgba(0,0,0,0)"`
   */
  bgcolor?: string;
  /**
   * Box border color.
   *
   * @defaultValue `"rgba(0,0,0,0)"`
   */
  bordercolor?: string;
  /**
   * Padding between text and border, px.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  borderpad?: number;
  /**
   * Box border width, px.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  borderwidth?: number;
  /**
   * Draw an arrow from the text to `x`/`y`; the text then sits at the tail (`ax`/`ay`).
   *
   * @defaultValue `true`
   */
  showarrow?: boolean;
  /**
   * Arrow color. Defaults to `bordercolor` when visible, else `#444`.
   */
  arrowcolor?: string;
  /**
   * End arrowhead: 0 none, 1 wide, 2 narrow, 3 barbed, 4–5 line-drawn, 6 circle, 7 square, 8 bar.
   *
   * Range: 0 – 8
   *
   * @defaultValue `1`
   */
  arrowhead?: number;
  /**
   * Start arrowhead (0–8).
   *
   * Range: 0 – 8
   *
   * @defaultValue `1`
   */
  startarrowhead?: number;
  /**
   * Which ends get an arrowhead.
   *
   * @defaultValue `"end"`
   */
  arrowside?: 'end' | 'start' | 'end+start' | 'start+end' | 'none';
  /**
   * End arrowhead size, relative to `arrowwidth`.
   *
   * Minimum: 0.3
   *
   * @defaultValue `1`
   */
  arrowsize?: number;
  /**
   * Start arrowhead size, relative to `arrowwidth`.
   *
   * Minimum: 0.3
   *
   * @defaultValue `1`
   */
  startarrowsize?: number;
  /**
   * Arrow line width, px. Defaults to 2 (twice a visible border width).
   *
   * Minimum: 0.1
   */
  arrowwidth?: number;
  /**
   * Gap between the arrowhead tip and `x`/`y`, px.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  standoff?: number;
  /**
   * Gap between the text box and the start of the arrow, px.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  startstandoff?: number;
  /**
   * Arrow tail x: px from the head (`axref: pixel`, default −10) or a position in `axref` units.
   */
  ax?: unknown;
  /**
   * Arrow tail y: px from the head, positive down (`ayref: pixel`, default −30) or a position in `ayref` units.
   */
  ay?: unknown;
  /**
   * `'pixel'`, or `'paper'` (0–1 across the plot area), an axis id (`'x'`, `'x2'`: data units of that axis; log axes take exponents, as `range` does) or `'<axis> domain'` (0–1 across that axis' domain).
   *
   * @defaultValue `"pixel"`
   */
  axref?: string;
  /**
   * `'pixel'`, or `'paper'` (0–1 across the plot area), an axis id (`'x'`, `'x2'`: data units of that axis; log axes take exponents, as `range` does) or `'<axis> domain'` (0–1 across that axis' domain).
   *
   * @defaultValue `"pixel"`
   */
  ayref?: string;
  /**
   * Reference of `x`: `'paper'` (0–1 across the plot area), an axis id (`'x'`, `'x2'`: data units of that axis; log axes take exponents, as `range` does) or `'<axis> domain'` (0–1 across that axis' domain).
   *
   * @defaultValue `"x"`
   */
  xref?: string;
  /**
   * Reference of `y`: `'paper'` (0–1 across the plot area), an axis id (`'x'`, `'x2'`: data units of that axis; log axes take exponents, as `range` does) or `'<axis> domain'` (0–1 across that axis' domain).
   *
   * @defaultValue `"y"`
   */
  yref?: string;
  /**
   * Anchor x (the arrow head). Defaults to the middle of the reference.
   */
  x?: unknown;
  /**
   * Anchor y (the arrow head). Defaults to the middle of the reference.
   */
  y?: unknown;
  /**
   * Which side of the text box sits at the anchor (or tail). `auto`: `center` with an arrow or a data reference, else by thirds of `x`.
   *
   * @defaultValue `"auto"`
   */
  xanchor?: 'auto' | 'left' | 'center' | 'right';
  /**
   * Which side of the text box sits at the anchor (or tail); `auto` as `xanchor`.
   *
   * @defaultValue `"auto"`
   */
  yanchor?: 'auto' | 'top' | 'middle' | 'bottom';
  /**
   * Shift the whole annotation right, px.
   *
   * @defaultValue `0`
   */
  xshift?: number;
  /**
   * Shift the whole annotation up, px.
   *
   * @defaultValue `0`
   */
  yshift?: number;
  /**
   * Toggle `visible` when a data point at `xclick`/`yclick` (default `x`/`y`) is clicked; `onout` also hides it on clicks on other points.
   *
   * @defaultValue `false`
   */
  clicktoshow?: false | 'onoff' | 'onout';
  /**
   * x of the point that toggles this annotation.
   */
  xclick?: unknown;
  /**
   * y of the point that toggles this annotation.
   */
  yclick?: unknown;
  /**
   * Hover text (declared; hover labels for annotations are not drawn yet).
   */
  hovertext?: string;
  /**
   * Hover label style (declared; not drawn yet).
   */
  hoverlabel?: LayoutAnnotationHoverlabel;
  /**
   * Take pointer events over the text box and emit `clickannotation` on click. Defaults to true with `hovertext`.
   */
