  /**
   * `scaled`: `y0`/`y1` (and path y values) are in `yref` units. `pixel`: they are px offsets from `yanchor` (positive up), so the shape keeps its size when zooming.
   *
   * @defaultValue `"scaled"`
   */
  ysizemode?: 'scaled' | 'pixel';
  /**
   * x anchor (in `xref` units) of a `pixel`-sized shape.
   */
  xanchor?: unknown;
  /**
   * y anchor (in `yref` units) of a `pixel`-sized shape.
   */
  yanchor?: unknown;
  /**
   * Start x. Default: 25% across the reference (px 0 when `pixel`).
   */
  x0?: unknown;
  /**
   * End x. Default: 75% across the reference (px 10 when `pixel`).
   */
  x1?: unknown;
  /**
   * Start y. Default: 25% up the reference (px 0 when `pixel`).
   */
  y0?: unknown;
  /**
   * End y. Default: 75% up the reference (px 10 when `pixel`).
   */
