  lineposition?:
    | 'under'
    | 'over'
    | 'through'
    | 'under+over'
    | 'under+through'
    | 'over+under'
    | 'over+through'
    | 'through+under'
    | 'through+over'
    | 'under+over+through'
    | 'under+through+over'
