/**
 * One item of `annotations`.
 *
 * Template defaults for every item go in `annotationdefaults`.
 */
export interface LayoutSceneAnnotation {
  /**
   * Draw this annotation.
   *
   * @defaultValue `true`
   */
  visible?: boolean;
  /**
   * Text. `<br>` breaks lines; `<b>`/`<i>` around the whole text, `<sup>`/`<sub>` digits and entities are rendered, other tags are dropped until rich text (E2.10).
   *
   * @defaultValue `""`
   */
  text?: string;
  /**
   * Rotation of the text box, degrees clockwise.
   *
   * @defaultValue `0`
   */
  textangle?: number;
  /**
   * Text font. Defaults to `layout.font`.
   */
  font?: LayoutAnnotationFont;
  /**
   * Box width (text area), px. Default: the text width.
   *
   * Minimum: 1
   */
  width?: number;
  /**
   * Box height (text area), px. Default: the text height.
   *
   * Minimum: 1
   */
  height?: number;
  /**
   * Opacity of the whole annotation.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  opacity?: number;
  /**
   * Horizontal alignment of the lines inside the box.
   *
   * @defaultValue `"center"`
   */
  align?: 'left' | 'center' | 'right';
  /**
   * Vertical alignment of the text inside the box (with `height`).
   *
   * @defaultValue `"middle"`
   */
  valign?: 'top' | 'middle' | 'bottom';
  /**
   * Box background.
   *
   * @defaultValue `"rgba(0,0,0,0)"`
   */
  bgcolor?: string;
  /**
   * Box border color.
   *
   * @defaultValue `"rgba(0,0,0,0)"`
   */
  bordercolor?: string;
  /**
   * Padding between text and border, px.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  borderpad?: number;
  /**
   * Box border width, px.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  borderwidth?: number;
  /**
   * Draw an arrow from the text to `x`/`y`; the text then sits at the tail (`ax`/`ay`).
   *
   * @defaultValue `true`
   */
  showarrow?: boolean;
  /**
   * Arrow color. Defaults to `bordercolor` when visible, else `#444`.
   */
  arrowcolor?: string;
  /**
   * End arrowhead: 0 none, 1 wide, 2 narrow, 3 barbed, 4–5 line-drawn, 6 circle, 7 square, 8 bar.
   *
   * Range: 0 – 8
   *
   * @defaultValue `1`
   */
  arrowhead?: number;
  /**
   * Start arrowhead (0–8).
   *
   * Range: 0 – 8
   *
   * @defaultValue `1`
   */
  startarrowhead?: number;
  /**
   * Which ends get an arrowhead.
   *
   * @defaultValue `"end"`
   */
  arrowside?: 'end' | 'start' | 'end+start' | 'start+end' | 'none';
  /**
   * End arrowhead size, relative to `arrowwidth`.
   *
   * Minimum: 0.3
   *
   * @defaultValue `1`
   */
  arrowsize?: number;
  /**
   * Start arrowhead size, relative to `arrowwidth`.
   *
   * Minimum: 0.3
   *
   * @defaultValue `1`
   */
  startarrowsize?: number;
  /**
   * Arrow line width, px. Defaults to 2 (twice a visible border width).
   *
   * Minimum: 0.1
   */
  arrowwidth?: number;
  /**
   * Gap between the arrowhead tip and `x`/`y`, px.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  standoff?: number;
  /**
   * Gap between the text box and the start of the arrow, px.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  startstandoff?: number;
  /**
   * Which side of the text box sits at the anchor (or tail). `auto`: `center` with an arrow or a data reference, else by thirds of `x`.
   *
   * @defaultValue `"auto"`
   */
  xanchor?: 'auto' | 'left' | 'center' | 'right';
  /**
   * Which side of the text box sits at the anchor (or tail); `auto` as `xanchor`.
   *
   * @defaultValue `"auto"`
   */
  yanchor?: 'auto' | 'top' | 'middle' | 'bottom';
  /**
   * Shift the whole annotation right, px.
   *
   * @defaultValue `0`
   */
  xshift?: number;
  /**
   * Shift the whole annotation up, px.
   *
   * @defaultValue `0`
   */
  yshift?: number;
  /**
   * Hover text (declared; hover labels for annotations are not drawn yet).
   */
  hovertext?: string;
  /**
   * Hover label style (declared; not drawn yet).
   */
  hoverlabel?: LayoutAnnotationHoverlabel;
  /**
   * Take pointer events over the text box and emit `clickannotation` on click. Defaults to true with `hovertext`.
   */
  captureevents?: boolean;
  /**
   * The x of the annotated point, in the scene x axis' data.
   */
  x?: unknown;
  /**
   * The y of the annotated point, in the scene y axis' data.
   */
  y?: unknown;
  /**
   * The z of the annotated point, in the scene z axis' data.
   */
  z?: unknown;
  /**
   * Arrow tail (the text) x offset from the point, px. Default −10.
   */
  ax?: number;
  /**
   * Arrow tail (the text) y offset from the point, px, positive down. Default −30.
   */
  ay?: number;
  /**
   * Name of this annotation, used to reference it from a template via `templateitemname`.
   */
  name?: string;
  /**
   * Name of a template annotation to inherit from. If no template item matches, this annotation is hidden (`visible: false`).
   */
  templateitemname?: string;
}

/**
 * The scene's lights (Holochart extension). Unset, traces are lit as in Plotly (each by its `lightposition`); set, these lights light every trace of the scene (Plotly's model scales them by the trace's `lighting`).
 */
export interface LayoutSceneLighting {
  /**
   * Light reaching every surface from every direction.
   */
  ambient?: LayoutSceneLightingAmbient;
  /**
   * Directional lights (like the sun). Default: one light at Plotly's default `lightposition` (clip space `(1e5, 1e5, 0)`); `[]` for none.
   */
  directional?: readonly LayoutSceneLightingLight[];
  /**
   * Sky and ground light blended by the surfaces' orientation to the scene's z axis.
   */
  hemisphere?: LayoutSceneLightingHemisphere;
  /**
   * Image-based lighting and reflections for the `standard`, `physical`, `phong` and `basic` material types: `'studio'`, `'city'` (built-in rooms) or the URL of an equirectangular image.
   */
  environment?: string;
  /**
   * Strength of the environment's light.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  environmentintensity?: number;
  /**
   * Shadows of lights with `castshadow`.
   */
  shadows?: LayoutSceneLightingShadows;
}

/**
 * Light reaching every surface from every direction.
 */
export interface LayoutSceneLightingAmbient {
  /**
   * Ambient color.
   *
   * @defaultValue `"#fff"`
   */
  color?: string;
  /**
   * Ambient intensity (1: the full color).
   *
   * Minimum: 0
   *
   * @defaultValue `0.8`
   */
  intensity?: number;
}

/**
 * One item of `directional`.
 *
 * Template defaults for every item go in `lightdefaults`.
 */
export interface LayoutSceneLightingLight {
  /**
   * Whether this light shines.
   *
   * @defaultValue `true`
   */
  visible?: boolean;
  /**
   * Light color.
   *
   * @defaultValue `"#fff"`
   */
  color?: string;
  /**
   * Light intensity (1: the full color).
   *
   * Minimum: 0
   *
   * @defaultValue `0.8`
   */
  intensity?: number;
  /**
   * Where the light shines from (see `space`). Default `(1, 1, 1)` (`(1e5, 1e5, 0)` in clip space).
   */
  position?: LayoutSceneLightingLightPosition;
  /**
   * `scene`: a direction in scene units, fixed to the data (the light shines from `position` toward the scene's center). `camera`: a direction in view space (x right, y up, z toward the viewer), moving with the view. `clip`: Plotly's `lightposition` space, moving with the view.
   *
   * @defaultValue `"scene"`
   */
  space?: 'scene' | 'camera' | 'clip';
  /**
   * Cast shadows (from traces with `material.castshadow`, onto three.js material types with `material.receiveshadow` and the ground plane).
   *
   * @defaultValue `false`
   */
  castshadow?: boolean;
  /**
   * Name of this light, used to reference it from a template via `templateitemname`.
   */
  name?: string;
  /**
   * Name of a template light to inherit from. If no template item matches, this light is hidden (`visible: false`).
   */
  templateitemname?: string;
}

/**
 * Where the light shines from (see `space`). Default `(1, 1, 1)` (`(1e5, 1e5, 0)` in clip space).
 */
export interface LayoutSceneLightingLightPosition {
  /**
   * x component.
   */
  x?: number;
  /**
   * y component.
   */
  y?: number;
  /**
   * z component.
   */
  z?: number;
}

/**
 * Sky and ground light blended by the surfaces' orientation to the scene's z axis.
 */
export interface LayoutSceneLightingHemisphere {
  /**
   * Color from above.
   *
   * @defaultValue `"#fff"`
   */
  skycolor?: string;
  /**
   * Color from below.
   *
   * @defaultValue `"#4d4d4d"`
   */
  groundcolor?: string;
  /**
   * Intensity. The hemisphere light is on when `hemisphere` is given.
   *
   * Minimum: 0
   *
   * @defaultValue `0.5`
   */
  intensity?: number;
}

/**
 * Shadows of lights with `castshadow`.
 */
export interface LayoutSceneLightingShadows {
  /**
   * A ground plane catching shadows, below the scene's axis box.
   *
   * @defaultValue `false`
   */
  ground?: boolean;
  /**
   * Half-size of the shadowed region, scene units. Default: large enough for the axis box.
   *
   * Minimum: 0
   */
  extent?: number;
  /**
   * Shadow map size, px.
   *
   * Range: 64 – 8192
   *
   * @defaultValue `1024`
   */
  mapsize?: number;
  /**
   * Darkness of the ground plane's shadows.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.3`
   */
  opacity?: number;
}

/**
 * Turn the scene continuously, like a turntable (Holochart extension). The rotation pauses while the user moves the camera and carries on from the new view when the camera comes to rest; it runs only while the chart is on screen, and not at all with reduced motion (`prefers-reduced-motion`). The layout camera doesn't follow the rotation: `relayout` reports the camera when a gesture or `animateCamera` ends, or the rotation stops.
 */
export interface LayoutSceneAutorotate {
  /**
   * Degrees per second the scene turns, counterclockwise seen from the positive end of `axis` (negative: clockwise). Default 15 when `autorotate` is given, else 0 (off).
   */
  speed?: number;
  /**
   * The axis the scene turns about, through the camera's `center`.
   *
   * @defaultValue `"z"`
   */
  axis?: 'x' | 'y' | 'z';
  /**
   * Freeze the rotation at this many seconds after the start (the layout camera turned by `speed × time`): a fixed frame for exports and tests.
   */
  time?: number;
}

/**
 * The 2.5D view (Holochart extension): every cartesian subplot in perspective, its plot area a tilted plane; axes, hover, zoom and selection keep working.
 */
export interface LayoutView3d {
  /**
   * Show the cartesian subplots in perspective (2.5D).
   *
   * @defaultValue `false`
   */
  enabled?: boolean;
  /**
   * Elevation of the view, degrees: positive looks from above (the tops of vertical bars show).
   *
   * Range: -80 – 80
   *
   * @defaultValue `20`
   */
  tilt?: number;
  /**
   * Azimuth of the view, degrees: positive looks from the right (right sides show).
   *
   * Range: -80 – 80
   *
   * @defaultValue `-20`
   */
  rotation?: number;
  /**
   * Strength of the perspective: 0 is a parallel projection, 1 a strong one.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.5`
   */
  perspective?: number;
  /**
   * With `dragmode` `'turntable'` or `'orbit'`, dragging the plot area turns the view.
   *
   * @defaultValue `true`
   */
  interactive?: boolean;
}
